/**
 * The antique look's cuts of type (`ANTIQUE_LABEL_STYLE` sizes each): letter-spaced
 * roman `capitals` for the titles (planets, regions), `roman` upper and lower case
 * for the middle tier (moons, clusters, nebulae), `italic` as named for the stars
 * and Cassini's numbered moons, and letter-spaced `spacedItalic` capitals for a
 * name strung along what it names, as the atlases lettered seas (the Galaxy's arms).
 */

export type AntiqueLettering = 'capitals' | 'roman' | 'italic' | 'spacedItalic';
